import React, { useState, useMemo, useEffect } from 'react';
import {
  Grid,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Typography,
} from '@mui/material';
import { useTranslation } from 'react-i18next';
import { formatDate, getPriceFormatWithoutCurrency } from '../../core/utils';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import { useNavigate, useParams } from 'react-router';
import { useGetAllCreditHistoryQuery } from '../posApi';
import { appColors } from '../../theme/appColors';
import { ICustomerDetailsData, ICustomerDetailsDataItem } from '../../core/Interface/customer.interface';

const CreditManage: React.FC = () => {
  const [page, setPage] = useState(0);
  const navigate = useNavigate();
  const { id: urlCreditId } = useParams();
  const [rowsPerPage, setRowsPerPage] = useState(10);

  useEffect(() => {

  }, [urlCreditId]);

  const { data: creditData } =
    useGetAllCreditHistoryQuery({
      customerId: urlCreditId,
    });

  const customerList = useMemo(() => {
    const creditHistoryData = creditData?.data as ICustomerDetailsDataItem;
    return creditHistoryData?.credithistory ?? [];
  }, [creditData?.data]);

  const handleChangePage = (event: unknown, newPage: number) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    setRowsPerPage(+event.target.value);
    setPage(0);
  };
  const { t } = useTranslation(['customer']);

  const customerName =
    (creditData?.data as ICustomerDetailsDataItem)?.customerName ?? '';
  const mobileNo =
    (creditData?.data as ICustomerDetailsDataItem)?.mobileNo ?? '';
  const Balance =
    ((creditData?.data as ICustomerDetailsDataItem)?.balance ?? 0) < 0
      ? ((creditData?.data as ICustomerDetailsDataItem)?.balance ?? 0) * -1
      : (creditData?.data as ICustomerDetailsDataItem)?.balance ?? 0;

  return (
    <>
      <Grid
        alignItems="center"
        container
        gap={2}
        mb={4}
        onClick={() => navigate(-1)}
        sx={{ cursor: 'pointer', px: 2 }}
      >
        <ArrowBackIosNewIcon />
        <Typography
          sx={{ fontWeight: 600 }}
          variant="h6"
        >
          Back
        </Typography>
      </Grid>
      <Typography
        sx={{ fontWeight: 600, textAlign: 'center', pb: 4 }}
        variant="h6"
      >
        Credit Management
      </Typography>
      <Grid
        container
        justifyContent="space-between"
        mb={4}
      >
        <Grid
          item
          lg={5}
          pl={2.5}
        >
          <Typography
            sx={{ fontWeight: 500 }}
            variant="body1"
          >
            <strong>Customer Name : </strong>
            {customerName}
          </Typography>
        </Grid>
        <Grid
          item
          lg={4}
        >
          <Typography
            sx={{ fontWeight: 500 }}
            variant="body1"
          >
            <strong>Mobile No : </strong> {mobileNo}
          </Typography>
        </Grid>
        <Grid
          item
          lg={3}
        >
          <Typography
            sx={{
              fontWeight: 500,
              color:
                (creditData?.data as ICustomerDetailsDataItem)?.balance <= 0
                  ? appColors.forestGreen[100]
                  : appColors.carmineRed[120],
            }}
            variant="body1"
          >
            <strong>Balance : {getPriceFormatWithoutCurrency(Balance)} </strong>
          </Typography>
        </Grid>
      </Grid>

      <Paper
        sx={{
          borderRadius: '5px',
          boxShadow: 'none',
          padding: '11px',
          width: '100%',
        }}
      >
        <TableContainer sx={{ overflowX: 'auto', width: '100%' }}>
          <Table
            sx={{
              minWidth: 550,
              borderCollapse: 'collapse',
            }}
          >
            <TableHead
              sx={{
                borderRadius: '8px',
              }}
            >
              <TableRow
                sx={{
                  height: '50px',
                }}
              >
                <TableCell
                  sx={{
                    fontWeight: 'bold',
                    fontSize: '16px',
                    textAlign: 'left',
                  }}
                >
                  <strong>#</strong>
                </TableCell>
                <TableCell
                  sx={{
                    fontWeight: 'bold',
                    fontSize: '16px',
                    textAlign: 'left',
                  }}
                >
                  <strong>{t('customer:title.date')}</strong>
                </TableCell>
                <TableCell
                  sx={{
                    fontWeight: 'bold',
                    fontSize: '16px',
                    textAlign: 'left',
                  }}
                >
                  <strong>{t('customer:title.details')}</strong>
                </TableCell>
                <TableCell
                  sx={{
                    fontWeight: 'bold',
                    fontSize: '16px',
                    textAlign: 'right',
                  }}
                >
                  <strong>{t('customer:title.paid')}</strong>
                </TableCell>
                <TableCell
                  sx={{
                    fontWeight: 'bold',
                    fontSize: '16px',
                    textAlign: 'right',
                  }}
                >
                  <strong>{t('customer:title.credit')}</strong>
                </TableCell>
                <TableCell
                  sx={{
                    fontWeight: 'bold',
                    fontSize: '16px',
                    textAlign: 'right',
                  }}
                >
                  <strong>{t('customer:title.balance')}</strong>
                </TableCell>
              </TableRow>
            </TableHead>

            <TableBody>
              {customerList.length === 0 ? (
                <TableRow>
                  <TableCell
                    align="center"
                    colSpan={6}
                  >
                    {/* Display message when there is no data */}
                    No data available
                  </TableCell>
                </TableRow>
              ) : (
                customerList
                  ?.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                  .map((row: ICustomerDetailsData, index: number) => (
                    <TableRow
                      key={index}
                      sx={{ borderRadius: '16px', height: '50px' }}
                    >
                      <TableCell
                        component="th"
                        scope="row"
                        sx={{ textAlign: 'left' }}
                      >
                        {index + 1}
                      </TableCell>
                      <TableCell sx={{ textAlign: 'left' }}>
                        {formatDate(new Date(row.dateTime))}
                      </TableCell>
                      <TableCell sx={{ textAlign: 'left' }}>
                        {row.remark}
                      </TableCell>

                      <TableCell sx={{ textAlign: 'right' }}>
                        {row.isPayment
                          ? getPriceFormatWithoutCurrency(Math.abs(row.amount))
                          : '-'}
                      </TableCell>
                      <TableCell sx={{ textAlign: 'right' }}>
                        {row.isPayment
                          ? '-'
                          : getPriceFormatWithoutCurrency(Math.abs(row.amount))}
                      </TableCell>

                      <TableCell
                        sx={{
                          color:
                            row.balance <= 0
                              ? appColors.forestGreen[100]
                              : appColors.carmineRed[120],
                          textAlign: 'right',
                        }}
                      >
                        <strong>
                          {' '}
                          {row.balance < 0
                            ? getPriceFormatWithoutCurrency(
                                Math.abs(row.balance)
                              )
                            : getPriceFormatWithoutCurrency(
                                Math.abs(row.balance)
                              )}
                        </strong>
                      </TableCell>
                    </TableRow>
                  ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <TablePagination
          component="div"
          count={customerList.length || 0}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          page={page}
          rowsPerPage={rowsPerPage}
          rowsPerPageOptions={[5, 10, 25]}
        />
      </Paper>
    </>
  );
};

export default CreditManage;
